    #include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node* prev;
    Node* next;

    Node(int x) {
        data = x;
        prev = nullptr;
        next = nullptr;
    }
};

// Function to rotate the doubly-linked list
Node* rotateDLL(Node* head, int p) {

    Node* tail = head;

    // Find the last node
    while (tail->next) {
        tail = tail->next;
    }

    // Make the list circular
    tail->next = head;
    head->prev = tail;

    // Move head and tail by the given position
    for (int count = 1; count <= p; count++) {
        head = head->next;
        tail = tail->next;
    }

    // Break the circular connection
    tail->next = nullptr;
    head->prev = nullptr;

    return head;
}

void printList(Node* head) {
    Node* curr = head;
    while (curr) {
        cout << curr->data;
        if (curr->next) cout << " ";
        curr = curr->next;
    }
    cout << endl;
}

int main() {

    Node* head = new Node(2);
    head->next = new Node(6);
    head->next->prev = head;
    head->next->next = new Node(5);
    head->next->next->prev = head->next;
    head->next->next->next = new Node(4);
    head->next->next->next->prev = head->next->next;

    int p = 3;
    head = rotateDLL(head, p);
    printList(head);

    return 0;
}


